mapper.select:
SELECT DISTINCT MBSA.ANLS_DT ,MBSA.BSTP_ID ,MBSA.BUS_ROUTE_ID ,MBSA.RIDE_USER_CNT ,MBSA.LNDI_USER_CNT ,MBSA.TRNSIT_USER_CNT ,MBSA.USE_YN ,GBR.ROUTE_NM ,GBR.ROUTE_TP ,GBS.STATION_NM as BSTP_NM ,MBSA.ETL_DT FROM MRT_BUS_STTN_ANAL MBSA INNER JOIN GGBIS_BUS_ROUTE GBR ON MBSA.BUS_ROUTE_ID = GBR.ROUTE_ID INNER JOIN GGBIS_BUS_STATION GBS ON MBSA.BSTP_ID = GBS.STATION_ID WHERE MBSA.BSTP_ID = #{stationId}
AND TO_CHAR(MBSA.ANLS_DT, 'YYYY') = #{searchYear}
AND TO_CHAR(MBSA.ANLS_DT,'D') BETWEEN '2' AND '6'
AND (TO_CHAR(MBSA.ANLS_DT,'D') = '1' OR TO_CHAR(MBSA.ANLS_DT,'D') = '7')
AND TO_CHAR(MBSA.ANLS_DT, 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
AND TO_CHAR(MBSA.ANLS_DT, 'HH24') BETWEEN '06' AND '10'
AND TO_CHAR(MBSA.ANLS_DT, 'HH24') BETWEEN '17' AND '20'
AND TO_CHAR(MBSA.ANLS_DT, 'HH24') BETWEEN #{startTime} AND #{endTime}
